  async function fetchNewApiSuccessRate(rowId:string,force=false):Promise<void>{const row=credentialRows.find((item)=>item.rowId===rowId);if(!row||!newApiSuccessRateEligible(row))return;const previous=newApiSuccessRateState(rowId);if(previous.loading||(!force&&previous.attempted))return;const generation=(newApiSuccessGenerations[rowId]??0)+1;newApiSuccessGenerations={...newApiSuccessGenerations,[rowId]:generation};newApiSuccessControllers.get(rowId)?.abort();const controller=new AbortController();newApiSuccessControllers.set(rowId,controller);setNewApiSuccessRateState(rowId,{...previous,loading:true,error:'',attempted:true});const baseUrl=normalizeUrl(urlRows.find((item)=>item.id===currentUrlRowId)?.value??'');const model=row.new_api_model?.trim()??'';const group=row.new_api_group?.trim()??'';const key=isCredentialPlaceholder(row.key)?'':row.key.trim();const signature=JSON.stringify({baseUrl,model,group,key});const isCurrent=():boolean=>modalOpen&&generation===newApiSuccessGenerations[rowId]&&newApiSuccessControllers.get(rowId)===controller&&(()=>{const current=credentialRows.find((item)=>item.rowId===rowId);return !!current&&signature===JSON.stringify({baseUrl:normalizeUrl(urlRows.find((item)=>item.id===currentUrlRowId)?.value??''),model:current.new_api_model?.trim()??'',group:current.new_api_group?.trim()??'',key:isCredentialPlaceholder(current.key)?'':current.key.trim()});})();try{const result=await api.post<unknown>(successRatePath(editingName||name),{base_url:baseUrl,bearer_key:key,model,group},controller.signal);if(!isCurrent())return;if(!result||typeof result!=='object'||!('success_rate'in result)||(result.success_rate!==null&&(typeof result.success_rate!=='number'||!Number.isFinite(result.success_rate))))throw new Error(t('error.newApiSuccessRateResponse'));setNewApiSuccessRateState(rowId,{value:result.success_rate as number|null,loading:false,error:'',attempted:true});}catch(cause){if(isCurrent()&&!isIntentionalAbort(cause,controller.signal))setNewApiSuccessRateState(rowId,{...newApiSuccessRateState(rowId),loading:false,error:message(cause),attempted:true});}finally{if(newApiSuccessControllers.get(rowId)===controller)newApiSuccessControllers.delete(rowId);}}
  function maybeFetchNewApiSuccessRate(rowId:string):void{const row=credentialRows.find((item)=>item.rowId===rowId);if(row&&newApiSuccessRateEligible(row))void fetchNewApiSuccessRate(rowId);}
