  function updateCredentialRateMultiplier(rowId:string,value:number):void{credentialRows=credentialRows.map((item)=>item.rowId===rowId?{...item,rate_multiplier:Number.isFinite(value)?Math.max(0,value):1}:item);}
  function updateCredentialRateAdjustment(rowId:string,value:number):void{credentialRows=credentialRows.map((item)=>item.rowId===rowId?{...item,rate_multiplier_adjustment:Number.isFinite(value)?Math.max(0,value):1}:item);}
  function updateConcurrencyThreshold(rowId:string,field:'concurrencyThresholdPrimary'|'concurrencyThresholdSecondary',value:number):void{credentialRows=credentialRows.map((item)=>item.rowId===rowId?{...item,[field]:Number.isFinite(value)?Math.max(0,value):0}:item);}
  function updateAvailabilityThreshold(rowId:string,field:'availabilityThresholdPrimary'|'availabilityThresholdSecondary',value:number):void{credentialRows=credentialRows.map((item)=>item.rowId===rowId?{...item,[field]:Number.isFinite(value)?Math.min(100,Math.max(0,value)):0}:item);}
  function selectNewApiGroup(rowId:string,value:string):void{credentialRows=credentialRows.map((row)=>row.rowId===rowId?{...row,new_api_group:value}:row);resetNewApiSuccessRate(rowId,true);queueMicrotask(()=>maybeFetchNewApiSuccessRate(rowId));}
  function updateNewApiModel(rowId:string,value:string):void{credentialRows=credentialRows.map((row)=>row.rowId===rowId?{...row,new_api_model:value}:row);resetNewApiSuccessRate(rowId);}
  function blurNewApiModel(rowId:string):void{maybeFetchNewApiSuccessRate(rowId);}
  function newApiGroupOptions(row:CredentialRow):Array<{value:string;label:string;disabled?:boolean}>{const options:Array<{value:string;label:string;disabled?:boolean}>=Object.keys(pricing).map((group)=>({value:group,label:group}));if(row.new_api_group&&!Object.hasOwn(pricing,row.new_api_group))options.unshift({value:row.new_api_group,label:t('provider.newApiGroupMissing',{group:row.new_api_group}),disabled:true});return options;}
  function newApiRate(row:CredentialRow):string{const ratio=row.new_api_group?pricing[row.new_api_group]:undefined;return ratio===undefined?'—':`${ratio}x`;}
  function specialRateAdjustment(row:CredentialRow):number{return Number.isFinite(row.rate_multiplier_adjustment)?Math.max(0,row.rate_multiplier_adjustment??1):1;}
  function selectBoundItem(rowId:string,value:string):void{const item=boundItems.find((candidate)=>candidate.name===value);if(!item)return;credentialRows=credentialRows.map((row)=>row.rowId===rowId?{...row,id:item.name,key:item.key}:row);startCapacityPolling(boundAccountId);}
  function reorderCredentials(next:CredentialRow[]):void{credentialRows=next;}
  function removeCredential(row:CredentialRow):void{if(credentialRows.length===1&&!boundAccountId)return;const index=credentialRows.findIndex((item)=>item.rowId===row.rowId);if(index<0)return;const next=credentialRows.filter((item)=>item.rowId!==row.rowId);if(currentCredentialRowId===row.rowId)currentCredentialRowId=next[index]?.rowId??next[0]?.rowId??'';credentialRows=next;if(!credentialRows.some((item)=>!!item.id.trim()&&!!item.key.trim()))stopCapacityPolling(false);}
  function protocolGroups():{label:string;items:string[]}[]{const adapted=Object.keys(selectedVendor.adapted_api_types);const known=selectedVendor.known_supported_api_types.filter((item)=>!adapted.includes(item));const other=allowedTypes().filter((item)=>!adapted.includes(item)&&!known.includes(item));return[{label:'',items:adapted},{label:t('provider.rosettaUnadapted'),items:known},{label:t('provider.maybeUnsupported',{provider:t(selectedVendor.label_key)}),items:other}].filter((group)=>group.items.length);}
  function invalidateDetection(): void { detectionGeneration+=1;detectingEncoding=false;detectionError=''; }
  function invalidateBinding():void{bindingGeneration+=1;bindingController?.abort();bindingController=null;pendingBoundAccountId='';bindingBusy=false;bindingError='';}
  function stopCapacityPolling(clearSnapshot=false):void{capacityGeneration+=1;capacityController?.abort();capacityController=null;if(capacityTimer!==null){clearInterval(capacityTimer);capacityTimer=null;}capacityBusy=false;capacityError='';if(clearSnapshot)capacityItems={};}
  function capacityEligible(accountId:string):boolean{return modalOpen&&!!editingName&&vendorId==='openai'&&variantId==='sub2api'&&boundAccountId===accountId&&credentialRows.some((row)=>!!row.id.trim()&&!!row.key.trim());}
  async function fetchCapacity(accountId:string):Promise<void>{if(!capacityEligible(accountId)||capacityBusy)return;const generation=capacityGeneration;const providerName=editingName;const controller=new AbortController();capacityController=controller;capacityBusy=true;capacityError='';const isCurrent=():boolean=>capacityEligible(accountId)&&generation===capacityGeneration&&providerName===editingName&&capacityController===controller;try{const result=await api.post<unknown>(capacityPath(providerName),{account_id:accountId},controller.signal);if(!isCurrent())return;capacityItems=parseCapacityItems(result);}catch(cause){if(isCurrent()&&!isIntentionalAbort(cause,controller.signal))capacityError=t('error.providerCapacityFetch',{error:message(cause)});}finally{if(isCurrent()){capacityBusy=false;capacityController=null;}}}
  function startCapacityPolling(accountId:string):void{if(!capacityEligible(accountId))return;if(capacityTimer===null){void fetchCapacity(accountId);capacityTimer=setInterval(()=>void fetchCapacity(accountId),30_000);}}
  async function fetchBoundItems(accountId:string,trigger:'open'|'select'):Promise<void>{const generation=++bindingGeneration;bindingController?.abort();const controller=new AbortController();bindingController=controller;const providerName=editingName;pendingBoundAccountId=trigger==='select'?accountId:'';bindingBusy=true;bindingError='';const isCurrent=():boolean=>modalOpen&&generation===bindingGeneration&&providerName===editingName&&(trigger==='open'||pendingBoundAccountId===accountId);try{const result=await api.post<unknown>(bindingPath(providerName),{account_id:accountId},controller.signal);if(!isCurrent())return;const items=parseBoundItems(result);boundItems=items;if(trigger==='select'){stopCapacityPolling(true);boundAccountId=accountId;credentialRows=[];currentCredentialRowId='';}else startCapacityPolling(accountId);}catch(cause){if(isCurrent()&&!isIntentionalAbort(cause,controller.signal))bindingError=t('error.providerBindingFetch',{error:message(cause)});}finally{if(isCurrent()){pendingBoundAccountId='';bindingBusy=false;bindingController=null;}}}
  function selectBinding(value:string):void{if(value===boundAccountId){invalidateBinding();return;}if(value===''){invalidateBinding();stopCapacityPolling(true);boundAccountId='';boundItems=[];return;}stopCapacityPolling(true);void fetchBoundItems(value,'select');}
  function clearCredentialDeleteConfirmation():void{credentialDeleteOpen=false;credentialDeleteGroups=[];pendingProviderBody=null;}
  function closeProviderModal(): void { invalidateDetection();invalidateBinding();invalidatePricing();invalidateNewApiSuccessRates();stopCapacityPolling(true);modalOpen=false;boundItems=[];clearCredentialDeleteConfirmation(); }
  function updateProviderName(value:string):void{if(detectionPath(value)!==detectionPath(name))invalidateDetection();name=value;}
  function clearForm(): void {
    invalidateDetection();invalidateBinding();invalidatePricing();invalidateNewApiSuccessRates();stopCapacityPolling(true);
    const url=urlRow('');const credential=credentialRow({uuid:crypto.randomUUID(),id:'primary',key:''});editingName=''; name=''; urlRows=[url]; currentUrlRowId=url.id; proxy=''; apiType=allowedTypes()[0] ?? ''; requestEncoding='passthrough'; detectionModel=''; detectingEncoding=false; detectionError=''; allowRedirects=false; autoRotateCredentials=true; softInterrupt=false; forceRosettaCompaction=false; vendorId='custom'; variantId='custom'; credentialRows=[credential];currentCredentialRowId=credential.rowId;boundAccountId='';boundItems=[];clearCredentialDeleteConfirmation();error='';
  }
  function openNew(): void { clearForm(); modalOpen=true; }
  async function openEdit(providerName: string, provider: Provider, clone = false): Promise<void> {
    invalidateDetection();invalidateBinding();invalidatePricing();invalidateNewApiSuccessRates();stopCapacityPolling(true);
    editingName = clone ? '' : providerName; name = clone ? `${providerName}-copy` : providerName; const urlStatuses=new Map((provider.base_url_statuses??[]).map((item)=>[item.base_url,item.status])); urlRows=(provider.base_urls??[]).map((value)=>urlRow(value,clone?undefined:urlStatuses.get(value)));if(!urlRows.length)urlRows=[urlRow('')];currentUrlRowId=urlRows.find((row)=>row.value===firstUrl(provider))?.id??urlRows[0].id; proxy=provider.proxy ?? '';
    apiType = allowedTypes().includes(provider.api_type ?? '') ? provider.api_type ?? '' : allowedTypes()[0] ?? '';
    vendorId=vendorById(provider.provider).id; requestEncoding=provider.request_encoding??'passthrough'; detectionModel=''; detectingEncoding=false; detectionError=''; allowRedirects=provider.allow_redirects === true; autoRotateCredentials=provider.auto_rotate_credentials !== false; softInterrupt=provider.soft_interrupt === true; forceRosettaCompaction=provider.force_rosetta_compaction === true; const credentialStatuses=new Map((provider.credential_statuses??[]).map((item)=>[item.id,item.status]));credentialRows=(provider.api_keys??[]).map((item)=>credentialRow({...item,uuid:clone?crypto.randomUUID():item.uuid,key:clone?'':item.key,new_api_group:clone?null:item.new_api_group??null,new_api_model:clone?null:item.new_api_model??null},clone?undefined:credentialStatuses.get(item.id)));if(!credentialRows.length)credentialRows=[credentialRow({uuid:crypto.randomUUID(),id:'primary',key:''})];currentCredentialRowId=credentialRows.find((row)=>row.id===(provider.current_api_key??credentialRows[0].id))?.rowId??credentialRows[0].rowId;boundAccountId=clone?'':provider.sub2api_account_id??'';boundItems=[];capacityItems={};pricing={};clearCredentialDeleteConfirmation();const legacyVendor=vendorById(vendorId);const legacyVariant=Object.entries(legacyVendor.variants).find(([id,item])=>id!=='custom'&&Object.values(item.endpoints).some((preset)=>comparableUrl(preset)===comparableUrl(firstUrl(provider))))?.[0]??'custom';variantId=vendorId==='openai'?(provider.openai_variant??(provider.sub2api_account_id?'sub2api':legacyVariant)):legacyVariant;newApiAggregationBin=clone?defaultAggregationBin(variantId):normalizeAggregationBin(provider.new_api_aggregation_bin,variantId);if(variantId!=='sub2api')boundAccountId='';if(variantId!=='new_api'&&variantId!=='sub2api')newApiAggregationBin=defaultAggregationBin(variantId);modalOpen=true;error='';if(boundAccountId&&variantId==='sub2api')void fetchBoundItems(boundAccountId,'open');if(variantId==='new_api'){void fetchPricing();queueMicrotask(fetchInitialNewApiSuccessRates);}
  }
  async function load(signal?: AbortSignal): Promise<void> { const [configResult,accountsResult]=await Promise.allSettled([api.get<Config>('/admin/api/config',signal),api.get<{accounts?:Account[]}>('/admin/api/accounts',signal)]);if(configResult.status==='fulfilled'){config=configResult.value;error='';}else if(!isIntentionalAbort(configResult.reason,signal))error=message(configResult.reason);if(accountsResult.status==='fulfilled'){accounts=(accountsResult.value.accounts??[]).filter((account)=>account.provider==='sub2api');accountsError='';}else if(!isIntentionalAbort(accountsResult.reason,signal)){accounts=[];accountsError=t('error.providerAccountsFetch',{error:message(accountsResult.reason)});}loading=false; }
  function referencedCredentialGroups(cause:unknown):string[]|null{if(!cause||typeof cause!=='object'||!('code'in cause)||typeof cause.code!=='string'||!cause.code.startsWith('provider_credential_references:'))return null;try{const value=JSON.parse(cause.code.slice('provider_credential_references:'.length));return Array.isArray(value)&&value.every((item)=>typeof item==='string')?value:null;}catch{return null;}}
  function providerBody():Record<string,unknown>|null{
    const normalizedUrls=urlRows.map((row)=>normalizeUrl(row.value));const currentUrl=normalizeUrl(urlRows.find((row)=>row.id===currentUrlRowId)?.value??'');if(!name.trim()||!apiType||!allowedTypes().includes(apiType)||normalizedUrls.some((value)=>!/^https?:\/\//i.test(value))||new Set(normalizedUrls).size!==normalizedUrls.length||!normalizedUrls.includes(currentUrl)){error=t('error.providerFieldsRequired');return null;}
    const normalizedCredentials=credentialRows.map((item)=>({uuid:item.uuid,id:item.id.trim(),key:item.key.trim(),...(variantId!=='sub2api'&&variantId!=='new_api'?{rate_multiplier:Number.isFinite(item.rate_multiplier)?Math.max(0,item.rate_multiplier??1):1}:{rate_multiplier_adjustment:specialRateAdjustment(item)}),...(isOpenAi()&&variantId==='new_api'&&item.new_api_group?{new_api_group:item.new_api_group}:{}),...(isOpenAi()&&variantId==='new_api'&&item.new_api_model?.trim()?{new_api_model:item.new_api_model.trim()}: {})}));const currentCredential=credentialRows.find((row)=>row.rowId===currentCredentialRowId)?.id.trim()??'';if(normalizedCredentials.some((item)=>!item.id||!item.key)||new Set(normalizedCredentials.map((item)=>item.id)).size!==normalizedCredentials.length||(autoRotateCredentials&&!normalizedCredentials.some((item)=>item.id===currentCredential))){error=t('error.providerCredentialRequired');return null;}
    const body:Record<string,unknown>={provider:vendorId,api_type:apiType,base_urls:normalizedUrls,current_base_url:currentUrl,api_keys:normalizedCredentials,auto_rotate_credentials:autoRotateCredentials,proxy:proxy.trim(),allow_redirects:allowRedirects};if(isOpenAi())body.openai_variant=variantId;if(variantId==='new_api'||variantId==='sub2api')body.new_api_aggregation_bin=newApiAggregationBin;if(autoRotateCredentials)body.current_api_key=currentCredential;if(variantId==='sub2api'&&boundAccountId)body.sub2api_account_id=boundAccountId;if(apiType==='chat')body.soft_interrupt=softInterrupt;if(apiType==='responses'){body.request_encoding=requestEncoding;body.force_rosetta_compaction=forceRosettaCompaction;}if(editingName&&editingName!==name.trim())body.rename_from=editingName;return body;
  }
  async function submitProvider(body:Record<string,unknown>,confirmedGroups?:string[]):Promise<void>{busy=true;error='';try{await api.put(`/admin/api/config/providers/${encodeURIComponent(name.trim())}`,confirmedGroups?{...body,confirm_credential_deletion:confirmedGroups}:body);clearCredentialDeleteConfirmation();closeProviderModal();notice=t('toast.providerSaved',{name:name.trim()});await load();}catch(cause){const groups=referencedCredentialGroups(cause);if(groups){credentialDeleteGroups=groups;pendingProviderBody=body;credentialDeleteOpen=true;}else error=message(cause);}finally{busy=false;}}
  async function confirmCredentialDeletion():Promise<void>{if(!pendingProviderBody)return;const body=pendingProviderBody;const confirmedGroups=[...credentialDeleteGroups];credentialDeleteOpen=false;await submitProvider(body,confirmedGroups);}
  async function save(): Promise<void> {
    if(busy||bindingBusy)return;const body=providerBody();if(body)await submitProvider(body);
  }
  function detectionBody():Record<string,unknown>|null{const providerName=name.trim();const model=detectionModel.trim();const currentUrl=normalizeUrl(urlRows.find((row)=>row.id===currentUrlRowId)?.value??'');const currentCredential=credentialRows.find((row)=>row.rowId===currentCredentialRowId);const credentialId=currentCredential?.id.trim()??'';const credentialKey=currentCredential?.key.trim()??'';if(!providerName||!model||!/^https?:\/\//i.test(currentUrl)||!credentialId||!credentialKey||!currentCredential)return null;const body:Record<string,unknown>={provider:vendorId,api_type:'responses',model,current_base_url:currentUrl,api_keys:[{uuid:currentCredential.uuid,id:credentialId,key:credentialKey}],current_api_key:credentialId,auto_rotate_credentials:autoRotateCredentials,proxy:proxy.trim(),allow_redirects:allowRedirects};if(editingName&&editingName!==providerName)body.rename_from=editingName;return body;}
  async function detectRequestEncoding():Promise<void>{const body=detectionBody();if(!body){detectionError=t('error.requestEncodingDetectionFields');return;}const signature=JSON.stringify(body);const generation=detectionGeneration;const path=detectionPath(name);const isCurrent=():boolean=>modalOpen&&generation===detectionGeneration&&path===detectionPath(name);detectingEncoding=true;detectionError='';error='';try{const result=await api.post<EncodingDetection>(path,body);if(!isCurrent())return;if(signature!==JSON.stringify(detectionBody())){detectionError=t('error.requestEncodingDetectionStale');return;}if(result.selected){requestEncoding=result.selected;notice=t('toast.requestEncodingDetected',{encoding:t(`provider.requestEncoding.${result.selected}`)});return;}detectionError=t('error.requestEncodingDetectionFailed',{identity:result.identity.error??'',zstd:result.zstd.error??''});}catch(cause){if(isCurrent())detectionError=message(cause);}finally{if(isCurrent())detectingEncoding=false;}}
  async function action(operation:()=>Promise<unknown>,success:string):Promise<void>{busy=true;error='';try{await operation();await load();notice=success;}catch(cause){error=message(cause);}finally{busy=false;}}
  async function toggle(providerName:string):Promise<void>{await action(()=>api.post(`/admin/api/config/providers/${encodeURIComponent(providerName)}/toggle`),t('toast.providerToggled'));}
  async function selectCurrent(providerName:string,baseUrl:string):Promise<void>{await action(()=>api.post(`/admin/api/config/providers/${encodeURIComponent(providerName)}/current-base-url`,{current_base_url:baseUrl}),t('toast.providerCurrentUrlChanged'));}
  async function selectCredential(providerName:string,credentialId:string):Promise<void>{await action(()=>api.post(`/admin/api/config/providers/${encodeURIComponent(providerName)}/current-base-url`,{credential_id:credentialId}),t('toast.providerCurrentCredentialChanged'));}
  function requestDelete(providerName:string):void{pendingDelete=providerName;deleteInput='';deleteOpen=true;}
  async function confirmDelete():Promise<void>{if(deleteInput!==pendingDelete)return;const providerName=pendingDelete;await action(()=>api.del(`/admin/api/config/providers/${encodeURIComponent(providerName)}?cascade=true`),t('toast.providerDeleted',{name:providerName}));deleteOpen=false;pendingDelete='';}
  onMount(()=>{const controller=new AbortController();void load(controller.signal);return()=>{controller.abort();stopCapacityPolling(true);bindingController?.abort();invalidateNewApiSuccessRates();};});
</script>

<ServerSettingsSection />
<div class="section">
  <div class="section-header"><h2>{t('section.providers')}</h2></div>
  {#if error}<div class="toast error show" role="alert">{error}</div>{/if}{#if notice}<div class="toast show" role="status">{notice}</div>{/if}
  <div class="provider-toolbar">
    {#if providerEntries.length > 6}<input placeholder={t('label.searchProviders')} bind:value={search} />{/if}
    <span class="provider-count">{providerEntries.length > 6 ? (search ? `${filteredEntries.length} / ${providerEntries.length}` : `${providerEntries.length}`) : ''}</span>
    <div class="view-toggle">
      <button class="btn btn-sm" class:active={view==='grid'} onclick={()=>setView('grid')} title={t('label.gridView')} aria-label={t('label.gridView')}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg></button>
      <button class="btn btn-sm" class:active={view==='list'} onclick={()=>setView('list')} title={t('label.listView')} aria-label={t('label.listView')}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg></button>
    </div>
    <button class="btn btn-primary btn-sm" onclick={openNew}>{t('btn.addProvider')}</button>
  </div>
  {#if loading}<p style="color:var(--text-dim)">{t('loading.providers')}</p>{:else}
    <div class="provider-grid" class:list-view={view==='list'}>
      {#each filteredEntries as [providerName, provider]}
        {@const enabled=provider.enabled!==false}{@const info=displayInfo(provider)}
        <div class="provider-card" class:disabled={!enabled} class:config-error={!!provider.validation_error}>
          <div class="card-header"><div class="name">{#if info.logo}<img class="provider-logo" class:invert-in-dark={info.invertLogo} src={info.logo} alt="" />{/if}{providerName}{#if provider.validation_error}<span class="badge badge-error" title={provider.validation_error}>{t('provider.configError')}</span>{/if}</div><label class="toggle" title={enabled?t('provider.enabled'):t('provider.disabled')}><input type="checkbox" checked={enabled} onchange={()=>void toggle(providerName)} /><span class="slider"></span></label></div>
          {#if view==='list'}
            <div class="field" title={`${info.vendor} · ${info.protocol}`}><code>{info.vendor} · {info.protocol}</code></div><div class="field" title={firstUrl(provider)}><code>{firstUrl(provider)}</code></div><div class="field"><code>{provider.api_keys?.find((item)=>item.id===provider.current_api_key)?.key ?? ''}</code></div>
          {:else}
            <div class="field">{t('label.providerVendor')}: <code>{info.vendor}</code></div><div class="field">{t('label.providerProtocol')}: <code>{info.protocol}</code></div>{#each provider.base_url_statuses??[] as item}<div class="provider-url-status" class:available={item.status==='available'} class:cooling={item.status==='cooling'}><code>{item.base_url}</code><span>{t(`provider.url.${item.status}`)}</span>{#if item.current}<span>{t('provider.url.current')}</span>{:else}<button class="btn btn-sm" aria-label={t('aria.makeBaseUrlCurrent',{url:item.base_url})} onclick={()=>void selectCurrent(providerName,item.base_url)}>{t('provider.url.select')}</button>{/if}</div>{/each}{#each provider.credential_statuses??[] as item}<div class="provider-url-status" class:available={item.status==='available'} class:cooling={item.status==='cooling'}><code>{provider.api_keys?.find((credential)=>credential.id===item.id)?.key ?? item.id}</code><span>{t(`provider.url.${item.status}`)}</span>{#if item.current}<span>{t('provider.url.current')}</span>{:else}<button class="btn btn-sm" aria-label={t('aria.makeCredentialCurrent',{id:item.id})} onclick={()=>void selectCredential(providerName,item.id)}>{t('provider.url.select')}</button>{/if}</div>{/each}{#if provider.proxy}<div class="field">{t('label.proxyShort')} <code>{provider.proxy}</code></div>{/if}
          {/if}
          <div class="actions"><button class="btn btn-sm" onclick={()=>void openEdit(providerName,provider,true)}>{t('btn.clone')}</button><button class="btn btn-sm" onclick={()=>void openEdit(providerName,provider)}>{t('btn.edit')}</button><button class="btn btn-sm btn-danger" onclick={()=>requestDelete(providerName)}>{t('btn.delete')}</button></div>
        </div>
      {:else}<p style="color:var(--text-dim)">{providerEntries.length?t('empty.searchResults'):t('empty.providers')}</p>{/each}
    </div>
  {/if}
</div>

<Modal open={modalOpen} className="provider-modal" labelledby="provider-modal-title" onclose={closeProviderModal}>
  {#snippet header()}<h3 id="provider-modal-title">{editingName?t('modal.editProvider'):t('modal.addProvider')}</h3>{/snippet}
  <div class="form-group"><label for="provName">{t('label.providerName')}</label><input id="provName" value={name} oninput={(event)=>updateProviderName(event.currentTarget.value)} placeholder={t('placeholder.providerName')} /></div>
  <div class="form-group"><label for="provProvider">{t('label.providerVendor')}</label><div class="provider-preset-row"><div class="type-logo-wrapper">{#if logoFor(selectedVendor)}<img class="type-logo-preview" class:invert-in-dark={providerLogoNeedsDarkInversion(selectedVendor.logo_shim)} src={logoFor(selectedVendor)} alt="" />{/if}<Dropdown id="provProvider" value={vendorId} options={vendors().map((vendor)=>({value:vendor.id,label:t(vendor.label_key)}))} fitViewport={true} onChange={(value:DropdownValue)=>chooseVendor(String(value))} /></div><Dropdown ariaLabel={t('aria.providerVariant')} value={variantId} options={variantOptions()} fitViewport={true} onChange={(value:DropdownValue)=>chooseVariant(String(value))} /></div></div>
  <div class="form-group"><label for="provApiType">{t('label.providerProtocol')}</label><Dropdown id="provApiType" value={apiType} options={protocolGroups().flatMap((group)=>group.items.map((item)=>({value:item,label:protocolLabel(item)})))} fitViewport={true} fitContent={true} menuAlign="left" onChange={(value:DropdownValue)=>chooseProtocol(String(value))} /></div>
  <div class="provider-options-divider" role="separator"></div>
  <div class="form-group">
    <div class="form-label">{t('label.baseUrls')}<Hint content={t('hint.docker')} /></div>
    <SortableTableEnhanced items={urlRows} currentId={currentUrlRowId} disabled={busy} verticalSeparators={true} onReorder={reorderUrls} onRemove={removeUrl} onCurrentChange={(row)=>{currentUrlRowId=row.id;}} getRowColorPreset={(row)=>rowColorPreset(row.status)} getCurrentLabel={(row)=>t('aria.makeBaseUrlCurrent',{url:row.value||t('label.baseUrl')})} getDragLabel={(row)=>t('aria.dragBaseUrl',{url:row.value||t('label.baseUrl')})} getRemoveLabel={(row)=>t('aria.removeBaseUrl',{url:row.value||t('label.baseUrl')})}>
      {#snippet header()}<th>{t('col.baseUrl')}</th><th>{t('col.status')}</th>{/snippet}
      {#snippet children(row,index)}<td><input aria-label={t('aria.baseUrl',{index:index+1})} value={row.value} oninput={(event)=>setUrl(row.id,event.currentTarget.value)} placeholder={t('placeholder.baseUrl')} /></td><td class="provider-sortable-status">{#if row.status}<span class:available={row.status==='available'} class:cooling={row.status==='cooling'}>{t(`provider.url.${row.status}`)}</span>{/if}</td>{/snippet}
    </SortableTableEnhanced>
    <div class="provider-key-actions"><button type="button" class="btn btn-sm" onclick={addUrl}>{t('btn.addBaseUrl')}</button></div>
  </div>
  {#if editingName&&isOpenAi()&&variantId==='sub2api'}
    <div class="form-group provider-binding">
      <label for="providerBinding">{t('label.providerBinding')}</label>
      <Dropdown id="providerBinding" className="provider-binding-dropdown" value={boundAccountId} options={bindingOptions()} fitViewport={true} fitContent={true} portal={true} onTriggerClick={prepareBindingMenu} onChange={(value:DropdownValue)=>selectBinding(String(value))} />
      {#if bindingBusy}<p class="provider-binding-message" role="status">{t('provider.bindingLoading')}</p>{/if}
      {#if accountsError}<p class="provider-binding-message error" role="alert">{accountsError}</p>{/if}
      {#if bindingError}<p class="provider-binding-message error" role="alert">{bindingError}</p>{/if}
      {#if capacityError}<p class="provider-binding-message error" role="alert">{capacityError}</p>{/if}
      {#if boundAccountId&&!accounts.some((account)=>account.id===boundAccountId)}<p class="provider-binding-message unavailable">{t('provider.bindingMissing',{id:boundAccountId})}</p>{/if}
    </div>
  {/if}
  <div class="form-group">
    <div class="form-label">{t('label.providerCredentials')}</div>
    <SortableTableEnhanced items={credentialRows} getId={(row)=>row.rowId} showCurrentControl={autoRotateCredentials} currentId={currentCredentialRowId} disabled={busy||bindingBusy} verticalSeparators={true} allowRemoveLast={!!boundAccountId} onReorder={reorderCredentials} onRemove={removeCredential} onCurrentChange={(row)=>{currentCredentialRowId=row.rowId;}} getRowColorPreset={(row)=>isMissingBoundItem(row)?'red':rowColorPreset(row.status)} getCurrentLabel={(row)=>t('aria.makeCredentialCurrent',{id:row.id||t('placeholder.credentialId')})} getDragLabel={(row)=>t('aria.dragCredential',{id:row.id||t('placeholder.credentialId')})} getRemoveLabel={(row)=>t('aria.removeCredential',{id:row.id||t('placeholder.credentialId')})}>
      {#snippet header()}<th>{t('col.credentialId')}</th><th>{t('col.credentialKey')}</th>{#if showPricingColumns()}{#if variantId==='new_api'}<th><div class="provider-group-header"><span>{t('col.newApiGroup')}</span><button type="button" class="btn btn-sm" disabled={pricingBusy} onclick={()=>void fetchPricing()}>{pricingBusy?t('provider.newApiPricingLoading'):t('btn.retryNewApiPricing')}</button></div>{#if pricingError}<div class="provider-binding-message error" role="alert">{pricingError}</div>{/if}</th><th><div class="provider-concurrency-header"><span>{t('col.newApiModel')}</span><Hint ariaLabel={t('aria.newApiModelHelp')} content={t('provider.newApiModelDescription')} /></div></th>{/if}<th>{t('col.rateMultiplier')}</th><th><div class="provider-concurrency-header"><span>{t('col.rateMultiplierAdjustment')}</span><Hint ariaLabel={t('aria.rateMultiplierAdjustmentHelp')} content={t('provider.rateMultiplierAdjustmentDescription')} /></div></th>{#if variantId==='new_api'}<th>{t('col.successRate')}</th><th class="provider-threshold-column"><div class="provider-concurrency-header"><span>{t('col.availabilityThreshold')}</span><Hint ariaLabel={t('aria.availabilityThresholdHelp')} content={t('provider.availabilityThresholdDescription')} /></div></th>{:else}<th>{t('col.availableConcurrency')}</th><th class="provider-threshold-column"><div class="provider-concurrency-header"><span>{t('col.availabilityThreshold')}</span><Hint ariaLabel={t('aria.availabilityThresholdHelp')} content={t('provider.sub2apiAvailabilityThresholdDescription')} /></div></th>{/if}{:else if showManualRateMultiplier()}<th>{t('col.rateMultiplier')}</th>{/if}<th>{t('col.status')}</th>{/snippet}
      {#snippet children(row)}
        <td>{#if boundAccountId}<Dropdown className="provider-binding-dropdown provider-bound-item-dropdown" ariaLabel={t('aria.credentialId',{id:row.id||t('label.selectOne')})} value={row.id} options={boundItemOptions(row)} fitViewport={true} fitContent={true} portal={true} onTriggerClick={prepareBindingMenu} onChange={(value:DropdownValue)=>selectBoundItem(row.rowId,String(value))} />{:else}<input type="text" aria-label={t('aria.credentialId',{id:row.id})} value={row.id} oninput={(event)=>updateCredential(row.rowId,'id',event.currentTarget.value)} placeholder={t('placeholder.credentialId')} />{/if}</td>
        <td>{#if boundAccountId}<input class="provider-bound-key" type="text" aria-label={t('aria.credentialKey',{id:row.id})} value={maskedCredential(row.key)} readonly />{:else}<CredentialEditor ariaLabel={t('aria.credentialKey',{id:row.id})} clearLabel={t('aria.clearCredentialKey',{id:row.id})} value={row.key} onchange={(value)=>updateCredential(row.rowId,'key',value)} placeholder={'${OPENAI_API_KEY}'} />{/if}</td>
        {#if boundAccountId}<td class="provider-bound-metric">{boundRate(row)}</td><td><label class="provider-manual-rate-input"><input type="number" min="0" step="0.01" aria-label={t('aria.rateMultiplierAdjustment',{id:row.id})} value={specialRateAdjustment(row)} oninput={(event)=>updateCredentialRateAdjustment(row.rowId,event.currentTarget.valueAsNumber)} /><span aria-hidden="true">x</span></label></td><td class="provider-bound-metric" aria-label={t('col.availableConcurrency')}>{boundConcurrency(row)}</td><td class="provider-threshold-column"><div class="provider-concurrency-threshold-inputs"><input type="number" min="0" step="1" aria-label={t('aria.availabilityThresholdPrimary')} value={row.concurrencyThresholdPrimary} oninput={(event)=>updateConcurrencyThreshold(row.rowId,'concurrencyThresholdPrimary',event.currentTarget.valueAsNumber)} /><input type="number" min="0" step="1" aria-label={t('aria.availabilityThresholdSecondary')} value={row.concurrencyThresholdSecondary} oninput={(event)=>updateConcurrencyThreshold(row.rowId,'concurrencyThresholdSecondary',event.currentTarget.valueAsNumber)} /></div></td>{:else if variantId==='new_api'}<td><Dropdown ariaLabel={t('aria.newApiGroup',{id:row.id})} value={row.new_api_group??''} options={newApiGroupOptions(row)} disabled={pricingBusy||!Object.keys(pricing).length} fitViewport={true} portal={true} onChange={(value:DropdownValue)=>selectNewApiGroup(row.rowId,String(value))} /></td><td><input class="provider-new-api-model" type="text" aria-label={t('aria.newApiModel',{id:row.id})} value={row.new_api_model??''} oninput={(event)=>updateNewApiModel(row.rowId,event.currentTarget.value)} onblur={()=>blurNewApiModel(row.rowId)} placeholder={t('placeholder.newApiModel')} /></td><td class="provider-bound-metric">{newApiRate(row)}</td><td><label class="provider-manual-rate-input"><input type="number" min="0" step="0.01" aria-label={t('aria.rateMultiplierAdjustment',{id:row.id})} value={specialRateAdjustment(row)} oninput={(event)=>updateCredentialRateAdjustment(row.rowId,event.currentTarget.valueAsNumber)} /><span aria-hidden="true">x</span></label></td><td class="provider-new-api-success-rate"><div class="provider-success-rate-value">{newApiSuccessRateText(row)}</div><button type="button" class="btn btn-sm" disabled={newApiSuccessRateState(row.rowId).loading} onclick={()=>void fetchNewApiSuccessRate(row.rowId,true)}>{newApiSuccessRateState(row.rowId).loading?t('btn.refreshingNewApiSuccessRate'):t('btn.refreshNewApiSuccessRate')}</button>{#if newApiSuccessRateState(row.rowId).error}<div class="provider-binding-message error" role="alert">{newApiSuccessRateState(row.rowId).error}</div>{/if}</td><td class="provider-threshold-column"><div class="provider-threshold-inputs"><label class="provider-threshold-input"><input type="number" min="0" max="100" step="1" aria-label={t('aria.availabilityThresholdPrimary')} value={row.availabilityThresholdPrimary} oninput={(event)=>updateAvailabilityThreshold(row.rowId,'availabilityThresholdPrimary',event.currentTarget.valueAsNumber)} /><span aria-hidden="true">%</span></label><label class="provider-threshold-input"><input type="number" min="0" max="100" step="1" aria-label={t('aria.availabilityThresholdSecondary')} value={row.availabilityThresholdSecondary} oninput={(event)=>updateAvailabilityThreshold(row.rowId,'availabilityThresholdSecondary',event.currentTarget.valueAsNumber)} /><span aria-hidden="true">%</span></label></div></td>{:else if showManualRateMultiplier()}<td><label class="provider-manual-rate-input"><input type="number" min="0" step="0.01" aria-label={t('aria.rateMultiplier',{id:row.id})} value={row.rate_multiplier??1} oninput={(event)=>updateCredentialRateMultiplier(row.rowId,event.currentTarget.valueAsNumber)} /><span aria-hidden="true">x</span></label></td>{/if}
        <td class="provider-sortable-status">{#if isMissingBoundItem(row)}<span class="unavailable">{t('provider.bindingUnavailable')}</span>{:else if row.status}<span class:available={row.status==='available'} class:cooling={row.status==='cooling'}>{t(`provider.url.${row.status}`)}</span>{/if}</td>
      {/snippet}
    </SortableTableEnhanced>
  <div class="provider-key-actions"><button type="button" class="btn btn-sm" disabled={bindingBusy||(!!boundAccountId&&!boundItems.some((item)=>!credentialRows.some((row)=>row.id===item.name)))} onclick={addCredential}>{t('btn.addCredential')}</button></div>
  </div>
  {#if isOpenAi()&&(variantId==='new_api'||variantId==='sub2api')}<div class="provider-options-divider" role="separator"></div><div class="form-group"><div class="form-label form-label-with-hint"><label for="provNewApiAggregationBin">{t(variantId==='new_api'?'label.newApiAggregationBin':'label.sub2apiRefreshInterval')}</label><Hint content={t(variantId==='new_api'?'provider.newApiAggregationBinDescription':'provider.sub2apiRefreshIntervalDescription')} /></div><Dropdown id="provNewApiAggregationBin" value={newApiAggregationBin} options={aggregationBinOptions()} fitViewport={true} fitContent={true} menuAlign="left" onChange={(value:DropdownValue)=>{newApiAggregationBin=String(value) as NewApiAggregationBin;}} /></div>{/if}
  <div class="form-group"><div class="checkbox-group"><label><input type="checkbox" bind:checked={autoRotateCredentials} /><span>{t('label.autoRotateCredentials')}</span></label><Hint content={t('provider.autoRotateCredentialsDescription')} /></div></div>
  {#if apiType==='responses'}<div class="provider-options-divider" role="separator"></div><div class="form-group"><div class="form-label form-label-with-hint"><label for="provRequestEncoding">{t('label.requestEncoding')}</label><Hint content={t('provider.requestEncodingDescription')} /></div><div class="request-encoding-row"><Dropdown id="provRequestEncoding" value={requestEncoding} options={['passthrough','identity','zstd'].map((value)=>({value,label:t(`provider.requestEncoding.${value}`)}))} fitViewport={true} fitContent={true} menuAlign="left" onChange={(value:DropdownValue)=>{requestEncoding=String(value) as RequestEncoding;}} /><input aria-label={t('label.requestEncodingDetectionModel')} bind:value={detectionModel} placeholder={t('placeholder.requestEncodingDetectionModel')} /><button type="button" class="btn btn-sm" disabled={detectingEncoding} onclick={()=>void detectRequestEncoding()}>{detectingEncoding?t('btn.detectingRequestEncoding'):t('btn.detectRequestEncoding')}</button></div>{#if detectionError}<pre class="request-encoding-error" role="alert">{detectionError}</pre>{/if}</div>{/if}
  {#if apiType==='responses'}<div class="form-group"><div class="checkbox-group"><label><input type="checkbox" bind:checked={forceRosettaCompaction} /><span>{t('label.forceRosettaCompaction')}</span></label><Hint content={t('provider.forceRosettaCompactionDescription')} /></div></div>{/if}
  <div class="provider-options-divider" role="separator"></div>
  <div class="form-group"><label for="provProxy">{t('label.proxyUrl')}<Hint content={t('hint.docker')} /></label><input id="provProxy" bind:value={proxy} placeholder={t('placeholder.proxyExample')} /></div>
  <div class="form-group checkbox-group"><label><input type="checkbox" bind:checked={allowRedirects} /><span>{t('label.allowRedirects')}</span></label></div>
  {#if apiType==='chat'}<div class="form-group"><div class="checkbox-group"><label><input type="checkbox" bind:checked={softInterrupt} /><span>{t('label.softInterrupt')}</span></label></div><p class="provider-option-description">{t('provider.softInterruptDescription')}</p></div>{/if}
  {#snippet actions()}<button class="btn" onclick={closeProviderModal}>{t('btn.cancel')}</button><button class="btn btn-primary" disabled={busy||bindingBusy} onclick={()=>void save()}>{t('btn.save')}</button>{/snippet}
</Modal>

<ConfirmDialog open={credentialDeleteOpen} title={t('confirm.deleteReferencedCredentialsTitle')} message={t('confirm.deleteReferencedCredentials',{groups:credentialDeleteGroups.join(', ')})} confirmLabel={t('btn.delete')} cancelLabel={t('btn.cancel')} closeLabel={t('btn.cancel')} intent="danger" confirmDisabled={busy} cancelDisabled={busy} onClose={clearCredentialDeleteConfirmation} onConfirm={()=>void confirmCredentialDeletion()} />

<style>
  :global(.modal.provider-modal) { width: 90vw; height: 90vh; }
  .provider-url-status{display:flex;align-items:center;gap:6px;margin:5px 0;padding:5px 7px;border-radius:var(--radius);font-size:11px}
  .provider-url-status.available{background:color-mix(in srgb,var(--green) 10%,transparent)}
  .provider-url-status.cooling{background:color-mix(in srgb,var(--orange) 12%,transparent)}
  .provider-url-status code{min-width:0;flex:1}
  .provider-sortable-status{white-space:nowrap;color:var(--text-dim);font-size:11px;font-weight:600}.provider-sortable-status .available{color:var(--green)}.provider-sortable-status .cooling{color:var(--orange)}
  .provider-sortable-status .unavailable,.provider-binding-message.error,.provider-binding-message.unavailable{color:var(--red)}
  .provider-binding-message{margin:6px 0 0;font-size:12px;color:var(--text-dim)}
  :global(.provider-bound-item-dropdown){display:flex;width:100%}:global(.provider-bound-item-dropdown .suu-dropdown__button){width:100%}
  :global(body:has(.provider-binding-dropdown .suu-dropdown__button[aria-expanded="true"])>.suu-dropdown__menu--portal){right:auto!important;width:max-content!important;max-width:var(--provider-binding-menu-max-width)!important}
  :global(body:has(.provider-binding-dropdown .suu-dropdown__button[aria-expanded="true"])>.suu-dropdown__menu--portal .suu-dropdown__panel){min-width:0;max-width:100%}
  :global(body:has(.provider-binding-dropdown .suu-dropdown__button[aria-expanded="true"])>.suu-dropdown__menu--portal .suu-dropdown__option){max-width:100%}
  :global(body:has(.provider-binding-dropdown .suu-dropdown__button[aria-expanded="true"])>.suu-dropdown__menu--portal .suu-dropdown__option .suu-dropdown__label){overflow:hidden;text-overflow:ellipsis}
  .provider-bound-key{width:100%;min-width:0}.provider-bound-metric{white-space:nowrap;text-align:center;color:var(--text-dim)}
  .provider-new-api-model{width:100%;min-width:50px;box-sizing:border-box}
  .provider-manual-rate-input{display:flex;align-items:center;justify-content:center;gap:3px;white-space:nowrap}.provider-manual-rate-input input{box-sizing:border-box;width:5.5em;min-width:5.5em}.provider-manual-rate-input span{color:var(--text-dim);font:12px var(--mono);text-transform:lowercase}
  .provider-new-api-success-rate{text-align:center;white-space:nowrap}.provider-success-rate-value{font-family:var(--mono);color:var(--text-dim);margin-bottom:4px}.provider-new-api-success-rate .provider-binding-message{white-space:normal;max-width:180px;margin-left:auto;margin-right:auto}
  .provider-group-header{display:flex;align-items:center;justify-content:space-between;gap:6px;white-space:nowrap}.provider-group-header .btn{flex:0 0 auto}.provider-group-header+.provider-binding-message{margin-top:4px}
  .provider-concurrency-header{display:flex;align-items:center;justify-content:center;gap:2px;flex-wrap:nowrap;white-space:nowrap}.provider-threshold-column{width:max-content;min-width:max-content;max-width:max-content}.provider-concurrency-threshold-inputs,.provider-threshold-inputs{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:4px;max-width:100%;margin:0 auto}.provider-concurrency-threshold-inputs{width:56px}.provider-concurrency-threshold-inputs input{box-sizing:border-box;flex:0 0 56px;width:56px;min-width:56px;padding:4px 3px;font:12px var(--mono);color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:var(--radius)}.provider-threshold-inputs{width:60px}.provider-threshold-input{display:flex;align-items:center;gap:2px;flex:0 0 60px;width:60px}.provider-threshold-input input{box-sizing:border-box;flex:1 1 auto;width:48px;min-width:0;padding:4px 3px;font:12px var(--mono);color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:var(--radius)}.provider-threshold-input span{color:var(--text-dim);font:12px var(--mono)}
  .provider-key-actions{display:flex;gap:6px;margin-top:6px}
  .provider-options-divider{border-top:1px solid var(--border);margin:-4px 0 14px}
  .request-encoding-row{display:grid;grid-template-columns:minmax(180px,1fr) minmax(160px,1fr) auto;gap:8px;align-items:center}
  .request-encoding-error{margin:8px 0 0;padding:8px;border:1px solid var(--red);border-radius:var(--radius);white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.45 monospace;color:var(--red);background:color-mix(in srgb,var(--red) 7%,transparent)}
  @media (max-width: 700px){.request-encoding-row{grid-template-columns:1fr}.request-encoding-row .btn{justify-self:start}}
</style>

<Modal open={deleteOpen} labelledby="delete-provider-title" onclose={()=>deleteOpen=false}>
  {#snippet header()}<h3 id="delete-provider-title">{t('confirm.deleteProviderTitle')}</h3>{/snippet}
  <p style="margin:8px 0 12px;color:var(--text-dim);font-size:13px">{t('confirm.typeProviderName',{name:pendingDelete})}</p>
  {#if affectedModels.length}<div style="margin-bottom:12px;padding:8px 12px;background:var(--bg);border:1px solid var(--border);border-radius:var(--radius);font-size:12px;max-height:120px;overflow-y:auto"><div style="color:#cf222e;font-weight:600;margin-bottom:4px">{t('confirm.affectedModels',{count:affectedModels.length})}</div>{#each affectedModels as model}<div style="color:var(--text-dim)">• {model}</div>{/each}</div>{/if}
  <div class="form-group"><input aria-label={t('aria.confirmProviderName')} bind:value={deleteInput} autocomplete="off" spellcheck="false" style="font-family:monospace" /></div>
  {#snippet actions()}<button class="btn" onclick={()=>deleteOpen=false}>{t('btn.cancel')}</button><button class="btn btn-danger" disabled={deleteInput!==pendingDelete||busy} onclick={()=>void confirmDelete()}>{t('btn.delete')}</button>{/snippet}
</Modal>
